"use strict";
let animeAirData=null,animeAirLoad='idle';
function loadAnimeAirData(){if(animeAirLoad!=='idle')return;animeAirLoad='loading';fetch('data/anime-airdates.json').then(r=>{if(!r.ok)throw Error('airdates');return r.json();}).then(d=>{if(!Array.isArray(d.shows))throw Error('airdates');animeAirData=d;animeAirLoad='ready';if(current.type==='anime'&&!animeTopic)navigate(current,false);}).catch(()=>{animeAirLoad='error';if(current.type==='anime'&&!animeTopic)navigate(current,false);});}
function animeAtDate(show,cutoff=date){const aired=show.episodes.filter(e=>e.date<=cutoff);return {count:aired.length,latest:aired.at(-1)||null};}
function animePrompt(s,n){if(s.id==='naruto')return n<20?['如果小队遇到必须一起完成的任务，谁会先伸出手？','是实力更重要，还是愿意把后背交给同伴更重要？']:n<81?['比赛会怎样改变他们的关系？','把今天能看到的动作和对话记下来，下一话再来核对。']:['旅途中的分别，会让人变得更坚强吗？','先从你刚看到的这一集出发，不引用后面的身份答案。'];if(s.id==='onepiece')return n<53?['下一位伙伴需要什么本领？','只是同船旅行，还是已经愿意为彼此停下脚步？']:['这一段旅程里的约定，还会在更远的海上响起吗？','哪一个不起眼的道具，值得抄进你的猜测本？'];if(s.id==='bleach')return n<16?['突然得到力量，日常生活会先改变哪一件事？','如果是你，会不会答应替别人承担这份责任？']:['眼前的规则与伙伴的选择，究竟该相信哪一个？','只用已经播出的线索，替下一集写三个可能。'];return ['这一集留下的问题，你会怎样解释？','不要搜索后来的结局，把自己的猜测先留在这里。'];}
function renderAnimeProgress(){loadAnimeAirData();if(!animeAirData)return `<section class="anime-progress"><h2>那一天，更新到哪一集？</h2><p>${animeAirLoad==='error'?'播出目录暂时未能载入。':'正在打开播出年表…'}</p>${animeAirLoad==='error'?'<button data-anime-air-retry>重新载入</button>':''}</section>`;return `<section class="anime-progress"><header><h2>${date} · 今晚追到这里</h2><p>日本原始电视播出日期 · 不含特别篇 · 与国内电视台、字幕组进度可能不同</p></header><div class="anime-air-grid">${animeAirData.shows.filter(s=>!['shippuden','bleach-tybw'].includes(s.id)||s.premiered<=date).map(s=>{const p=animeAtDate(s);if(!p.latest)return `<article class="anime-not-started"><h3>${s.name}</h3><p>这个日期还没有开播</p></article>`;return `<article><img src="${s.image}" alt="${escapeHTML(s.name)}早期动画画面" loading="lazy"><small>初期集数画面 · ${s.imageDate} · 图片权利归原作方</small><h3>${s.name}</h3><b>截至当日，已播 ${p.count} 集</b><p>最近播出：${p.latest.date}</p><p class="anime-ep-title">${escapeHTML(p.latest.title)}</p><details><summary>最近五次更新</summary><ol>${s.episodes.filter(e=>e.date<=date).slice(-5).map(e=>`<li><time>${e.date}</time> ${escapeHTML(e.title)}</li>`).join('')}</ol></details><section class="anime-next-guess"><h4>等下一话的时候，聊聊这些</h4>${animePrompt(s,p.count).map(t=>`<p>${t}</p>`).join('')}<button data-anime-quick-topic="${s.id}">进猜测楼留一句</button></section><a href="${p.latest.url}" target="_blank" rel="noopener noreferrer">播出资料 / TVmaze ↗</a></article>`;}).join('')}</div><footer>集数为所收录常规集的累计顺序，英文集名沿用数据源，季编号不直接当作全剧集号。数据：<a href="https://www.tvmaze.com/api" target="_blank" rel="noopener noreferrer">TVmaze</a>，<a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 4.0</a>；截至2025年末的离线目录。下方讨论是新创作，不是旧论坛原帖。</footer></section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-anime-air-retry],[data-anime-quick-topic]');if(!b)return;if(b.hasAttribute('data-anime-air-retry')){animeAirLoad='idle';return navigate(current,false);}const ids={naruto:'naruto-family',shippuden:'later-guess',onepiece:'onepiece-crew',bleach:'bleach-power','bleach-tybw':'later-guess'};animeTopic=ids[b.dataset.animeQuickTopic];if(!animeTopicAvailable(animeTopics.find(t=>t.id===animeTopic)))animeTopic='anime-notebook';navigate(current,false);});
